class Solution {
    private class Node{
        val next=arrayOfNulls<Node>(26);
        var id=-1
    }
    private lateinit var root:Node;
    private fun getId(word:String,ids:HashMap<String,Int>):Int{
        val found=ids[word];
        if(found!=null)return found;
        val id=ids.size;
        ids[word]=id;
        var node=root;
        for(letter in word){
            val index=letter-'a';
            if(node.next[index]==null)node.next[index]=Node();
            node=node.next[index]!!
        };
        node.id=id;
        return id
    }
    fun minimumCost(source:String,target:String,original:Array<String>,changed:Array<String>,cost:IntArray):Long{
        root=Node();
        val ids=HashMap<String,Int>();
        for(i in cost.indices){
            getId(original[i],ids);
            getId(changed[i],ids)
        };
        val infinity=Long.MAX_VALUE/4;
        val distance=Array(ids.size){
            from->LongArray(ids.size){
                to->if(from==to)0L else infinity
            }
        };
        for(i in cost.indices){
            val from=ids[original[i]]!!;
            val to=ids[changed[i]]!!;
            distance[from][to]=minOf(distance[from][to],cost[i].toLong())
        };
        for(middle in distance.indices)for(from in distance.indices)if(distance[from][middle]<infinity)for(to in distance.indices)if(distance[middle][to]<infinity)distance[from][to]=minOf(distance[from][to],distance[from][middle]+distance[middle][to]);
        val dp=LongArray(source.length+1){
            infinity
        };
        dp[0]=0;
        for(start in source.indices){
            if(dp[start]==infinity)continue;
            if(source[start]==target[start])dp[start+1]=minOf(dp[start+1],dp[start]);
            var fromNode=root;
            var toNode=root;
            for(end in start until source.length){
                val nextFrom=fromNode.next[source[end]-'a']?:break;
                val nextTo=toNode.next[target[end]-'a']?:break;
                fromNode=nextFrom;
                toNode=nextTo;
                if(fromNode.id>=0&&toNode.id>=0&&distance[fromNode.id][toNode.id]<infinity)dp[end+1]=minOf(dp[end+1],dp[start]+distance[fromNode.id][toNode.id])
            }
        };
        return if(dp[source.length]==infinity)-1 else dp[source.length]
    }
}

